namespace Og.Core.Model;

/// <summary>
/// Somebody who went out through the door alive, kept by the door afterwards.
///
/// This is the fourth thing in this world that outlives the person it belonged
/// to, and the first one that is not a kind of wreckage. The others are all
/// what is left when something goes wrong: a corpse spills its pockets onto the
/// floor (<see cref="Item"/> on the ground), a place remembers who died on it
/// (<see cref="Fallen"/>), and what somebody said with nobody there to hear it
/// stays on the wall (<see cref="Words"/>). Every permanent mark in this cave
/// was a failure.
///
/// Meanwhile twelve people have got out. Rook twice, Tanril after an hour and
/// three quarters, Wick in twenty-five seconds flat, Malcolm carrying most of
/// the movable world, and Simon — who killed the goblin, walked away, came back
/// forty-five minutes later after reading a stranger's carved note, fed it
/// instead, and said "thank you!" to an empty room. Not one of them left a
/// trace. The door they opened says exactly what it said before anybody had
/// ever opened it.
///
/// So the door keeps them: a name, how long they were down here, and what they
/// walked out carrying. It is not a scoreboard — there is no ranking and
/// nothing to beat — it is the world being able to tell the next person
/// standing in front of that lock that the lock opens, that people have gone
/// through it, and roughly what it cost them. Everything else this world
/// remembers is a reason to be careful. This is the one reason to keep going.
/// </summary>
/// <param name="Name">What they were called. Not their id — a life is not linked to any other.</param>
/// <param name="LifetimeSeconds">Birth to the door. The whole of it.</param>
/// <param name="Carried">What went out with them, already written as a person would say it.</param>
/// <param name="At">When.</param>
public sealed record Survivor(
    string Name,
    int LifetimeSeconds,
    string Carried,
    DateTimeOffset At)
{
    public bool Matches(string name) =>
        name.Trim().Length > 0
        && string.Equals(Name, name.Trim(), StringComparison.OrdinalIgnoreCase);
}

using Og.Core.Definitions;
using Og.Core.Model;

namespace Og.Core.Runtime;

/// <summary>
/// A way a place reads, and what has to be true for it to read that way. See
/// <see cref="DescriptionVariantDefinition"/> for why these exist.
/// </summary>
public sealed class DescriptionVariant
{
    public string[] If { get; }
    public string[] IfNot { get; }
    public string Description { get; }

    public DescriptionVariant(DescriptionVariantDefinition definition)
    {
        If = definition.If;
        IfNot = definition.IfNot;
        Description = definition.Description;
    }

    public bool Holds(World world, Session session)
    {
        foreach (var condition in If)
        {
            if (!world.HasCondition(session, condition))
            {
                return false;
            }
        }

        foreach (var condition in IfNot)
        {
            if (world.HasCondition(session, condition))
            {
                return false;
            }
        }

        return true;
    }
}

public sealed class Location
{
    /// <summary>
    /// How many of its dead a place keeps. Deep enough that nobody in this
    /// world's lifetime will fall off the end of it, shallow enough that the
    /// stored overlay cannot grow without bound.
    /// </summary>
    public const int RemembranceLimit = 24;

    /// <summary>
    /// How much of what has been said here a place keeps. Shallower than its
    /// dead on purpose: a room that opens with twenty strangers' sentences is a
    /// guestbook, and nobody reads a guestbook. The oldest fall off, so what is
    /// here is what was said recently, by people who may still be alive.
    /// </summary>
    public const int SpokenLimit = 8;

    /// <summary>
    /// How many of the people who got out a door keeps. The same depth as the
    /// dead, because the two lists are the same question asked twice and it
    /// would be a strange world that forgot its successes faster.
    /// </summary>
    public const int SurvivorLimit = 24;

    public int Id { get; }
    public string Name { get; }
    public string Description { get; set; }
    public bool IsExit { get; }

    /// <summary>
    /// Other ways this place can read, in the order the world file wrote them.
    /// The first whose conditions hold wins; otherwise <see cref="Description"/>.
    /// </summary>
    public IReadOnlyList<DescriptionVariant> DescriptionVariants { get; }

    public int North { get; set; }
    public int East { get; set; }
    public int South { get; set; }
    public int West { get; set; }

    /// <summary>Shared across all players: one player killing it clears it for everyone.</summary>
    public Monster? Monster { get; set; }

    /// <summary>The creature the world file declares belongs here, if any.</summary>
    public string? AuthoredMonster { get; }

    /// <summary>When this location's creature was last killed, if it was.</summary>
    public DateTimeOffset? ClearedAt { get; set; }

    /// <summary>Seconds before a slain creature returns here. Zero means it stays dead.</summary>
    public int RespawnSeconds { get; set; }

    /// <summary>Items dropped here, visible to everyone in the room.</summary>
    public List<Item> Items { get; } = [];

    /// <summary>
    /// Everyone who has died here, oldest first. Outlives every one of them and
    /// every world restart; see <see cref="Model.Fallen"/> for why.
    /// </summary>
    public List<Fallen> Dead { get; } = [];

    /// <summary>
    /// What has been said here to nobody, oldest first. Outlives the speaker;
    /// see <see cref="Model.Words"/> for why.
    /// </summary>
    public List<Words> Spoken { get; } = [];

    /// <summary>
    /// Everyone who went out through here alive, oldest first. In practice only
    /// an exit ever has any; see <see cref="Model.Survivor"/> for why it is kept
    /// at all.
    /// </summary>
    public List<Survivor> Survivors { get; } = [];

    public List<Interaction> Interactions { get; } = [];

    public Location(LocationDefinition definition)
    {
        Id = definition.Index;
        Name = definition.Name;
        Description = definition.Description;
        DescriptionVariants = [.. definition.DescriptionWhen.Select(variant => new DescriptionVariant(variant))];
        IsExit = definition.IsExit;
        North = definition.Connections.North;
        East = definition.Connections.East;
        South = definition.Connections.South;
        West = definition.Connections.West;
        AuthoredMonster = definition.Monster;
    }

    /// <summary>Adds somebody to this place's dead, dropping the oldest past the limit.</summary>
    public void Remember(Fallen who)
    {
        Dead.Add(who);

        if (Dead.Count > RemembranceLimit)
        {
            Dead.RemoveRange(0, Dead.Count - RemembranceLimit);
        }
    }

    /// <summary>Leaves words here, dropping the oldest past the limit.</summary>
    public void Keep(Words words)
    {
        Spoken.Add(words);

        if (Spoken.Count > SpokenLimit)
        {
            Spoken.RemoveRange(0, Spoken.Count - SpokenLimit);
        }
    }

    /// <summary>Adds somebody to the people who got out here, oldest dropped past the limit.</summary>
    public void RecordEscape(Survivor who)
    {
        Survivors.Add(who);

        if (Survivors.Count > SurvivorLimit)
        {
            Survivors.RemoveRange(0, Survivors.Count - SurvivorLimit);
        }
    }

    /// <summary>The most recent person of that name to die here, if any.</summary>
    public Fallen? FindDead(string name)
    {
        for (var index = Dead.Count - 1; index >= 0; index--)
        {
            if (Dead[index].Matches(name))
            {
                return Dead[index];
            }
        }

        return null;
    }

    /// <summary>The most recent person of that name to get out here, if any.</summary>
    public Survivor? FindSurvivor(string name)
    {
        for (var index = Survivors.Count - 1; index >= 0; index--)
        {
            if (Survivors[index].Matches(name))
            {
                return Survivors[index];
            }
        }

        return null;
    }

    public int Exit(Direction direction) => direction switch
    {
        Direction.North => North,
        Direction.East => East,
        Direction.South => South,
        Direction.West => West,
        _ => 0
    };

    public IEnumerable<Direction> OpenDirections()
    {
        if (North > 0) yield return Direction.North;
        if (East > 0) yield return Direction.East;
        if (South > 0) yield return Direction.South;
        if (West > 0) yield return Direction.West;
    }
}

public enum Direction
{
    North,
    East,
    South,
    West
}

namespace Og.Core.Persistence;

/// <summary>
/// A character's full state, flattened for storage. Items are stored by name
/// because items are world data, not code.
/// </summary>
public sealed record CharacterSnapshot
{
    public required string Id { get; init; }
    public required string Name { get; init; }
    public int HitPoints { get; init; }
    public int MaxHitPoints { get; init; }
    public int LocationId { get; init; }

    public string[] Inventory { get; init; } = [];
    public string? Weapon { get; init; }
    public string? Armor { get; init; }

    public string[] Conditions { get; init; } = [];
    public string[] DisabledInteractions { get; init; } = [];
    public string[] FiredInteractions { get; init; } = [];
    public Dictionary<string, string> Attributes { get; init; } = [];

    public DateTimeOffset BornAt { get; init; } = DateTimeOffset.UtcNow;
    public DateTimeOffset? DiedAt { get; init; }
    public string? CauseOfDeath { get; init; }

    /// <summary>
    /// Whether this character went out through the door alive. A life can end two
    /// ways here and this is the other one; it is kept in <see cref="Attributes"/>
    /// so that it needs no column of its own.
    /// </summary>
    public bool HasEscaped => Attributes.ContainsKey("escaped_at");

    /// <summary>
    /// Whether this life is over — killed or walked out. Storage asks this
    /// question to decide whether a returning visitor picks their character back
    /// up or names a new one, and the answer is the same either way: they do not
    /// come back. <see cref="DiedAt"/> remains the record of actual death, and
    /// <see cref="HasEscaped"/> of the other ending; only this asks about both.
    /// </summary>
    public bool IsDead => DiedAt is not null || HasEscaped;
}

public sealed record MonsterState(string Name, int HitPoints);

/// <summary>
/// One of a place's dead, flattened for storage.
///
/// This is deliberately not a reference to a character row. A life here is
/// singular and nothing may link one to another, and a place's dead are not the
/// characters — they are what the floor kept of them: a name, what did it, how
/// long they lasted, and what fell out of their hands.
/// </summary>
public sealed record FallenState(
    string Name,
    string Cause,
    int LifetimeSeconds,
    string Carried,
    long At);

/// <summary>
/// Something said in a place and left there, flattened for storage. A name and
/// a sentence; no link to the character, who is very likely dead by the time
/// anybody reads it.
/// </summary>
public sealed record WordsState(string Speaker, string Text, long At);

/// <summary>
/// One of the people who got out through a door, flattened for storage. Like
/// <see cref="FallenState"/> it is not a reference to a character row: what the
/// door kept is a name, how long they were down here, and what went out with
/// them. The character itself is finished and nothing may reach back into it.
/// </summary>
public sealed record SurvivorState(
    string Name,
    int LifetimeSeconds,
    string Carried,
    long At);

/// <summary>
/// Everything mutable about the world that is not in its definition file. The
/// file is the world as authored; this is what has happened to it since.
/// </summary>
public sealed record WorldSnapshot
{
    public string[] Conditions { get; init; } = [];
    public string[] DisabledInteractions { get; init; } = [];
    public string[] EnabledInteractions { get; init; } = [];
    public Dictionary<int, string> LocationDescriptions { get; init; } = [];
    public Dictionary<int, string[]> GroundItems { get; init; } = [];

    /// <summary>Who has died where. Outlives every character in it.</summary>
    public Dictionary<int, FallenState[]> Dead { get; init; } = [];

    /// <summary>What has been said where, and left there. Outlives the speaker.</summary>
    public Dictionary<int, WordsState[]> Spoken { get; init; } = [];

    /// <summary>Who has got out where, and with what. Outlives them too.</summary>
    public Dictionary<int, SurvivorState[]> Survivors { get; init; } = [];

    /// <summary>
    /// Locations whose monster has been killed, and what stood there. A location
    /// absent from this is left as the world file declares it, so a creature newly
    /// written into a place is not wiped by the record of that place being empty.
    /// </summary>
    public Dictionary<int, MonsterState?> Monsters { get; init; } = [];

    /// <summary>When each cleared location's monster fell, for working out returns.</summary>
    public Dictionary<int, long> ClearedAt { get; init; } = [];
}

using Og.Core.Model;
using Og.Core.Runtime;

namespace Og.Core.Persistence;

/// <summary>Converts live world objects to and from their stored form.</summary>
public static class SnapshotMapper
{
    // ---- characters ---------------------------------------------------------

    public static CharacterSnapshot ToSnapshot(this Character character) => new()
    {
        Id = character.Id,
        Name = character.Name,
        HitPoints = character.HitPoints,
        MaxHitPoints = character.MaxHitPoints,
        LocationId = character.CurrentLocationId,
        Inventory = [.. character.Inventory.Select(item => item.Name)],
        Weapon = character.Weapon?.Name,
        Armor = character.Armor?.Name,
        Conditions = [.. character.Conditions],
        DisabledInteractions = [.. character.DisabledInteractions],
        FiredInteractions = [.. character.FiredInteractions],
        Attributes = new Dictionary<string, string>(character.Attributes),
        BornAt = character.BornAt,
        DiedAt = character.DiedAt,
        CauseOfDeath = character.CauseOfDeath
    };

    public static Character ToCharacter(this CharacterSnapshot snapshot, World world)
    {
        var character = new Character(snapshot.Id, snapshot.Name, snapshot.BornAt, snapshot.DiedAt, snapshot.CauseOfDeath)
        {
            MaxHitPoints = snapshot.MaxHitPoints,
            HitPoints = snapshot.HitPoints,
            CurrentLocationId = snapshot.LocationId,
            Weapon = Resolve(world, snapshot.Weapon),
            Armor = Resolve(world, snapshot.Armor)
        };

        foreach (var name in snapshot.Inventory)
        {
            if (world.CreateItem(name) is { } item)
            {
                character.Inventory.Add(item);
            }
        }

        foreach (var condition in snapshot.Conditions) character.Conditions.Add(condition);
        foreach (var id in snapshot.DisabledInteractions) character.DisabledInteractions.Add(id);
        foreach (var id in snapshot.FiredInteractions) character.FiredInteractions.Add(id);
        foreach (var (key, value) in snapshot.Attributes) character.Attributes[key] = value;

        return character;
    }

    private static Item? Resolve(World world, string? name) =>
        name is null ? null : world.CreateItem(name);

    // ---- world --------------------------------------------------------------

    public static WorldSnapshot ToSnapshot(this World world, IReadOnlyDictionary<int, string> authoredDescriptions)
    {
        var disabled = new List<string>();
        var enabled = new List<string>();

        foreach (var interaction in world.AllInteractions())
        {
            if (interaction.Id is not { Length: > 0 } id)
            {
                continue;
            }

            (interaction.DisabledForWorld ? disabled : enabled).Add(id);
        }

        return new WorldSnapshot
        {
            Conditions = [.. world.Conditions],
            DisabledInteractions = [.. disabled],
            EnabledInteractions = [.. enabled],
            LocationDescriptions = world.Locations
                .Where(location => !authoredDescriptions.TryGetValue(location.Id, out var authored)
                                   || authored != location.Description)
                .ToDictionary(location => location.Id, location => location.Description),
            GroundItems = world.Locations
                .Where(location => location.Items.Count > 0)
                .ToDictionary(location => location.Id,
                              location => location.Items.Select(item => item.Name).ToArray()),
            // The dead are kept whatever else changes. A room may be rewritten,
            // renamed or emptied of everything else and whoever died on that
            // floor still died on it.
            Dead = world.Locations
                .Where(location => location.Dead.Count > 0)
                .ToDictionary(
                    location => location.Id,
                    location => location.Dead
                        .Select(fallen => new FallenState(
                            fallen.Name,
                            fallen.Cause,
                            fallen.LifetimeSeconds,
                            fallen.Carried,
                            fallen.At.ToUnixTimeSeconds()))
                        .ToArray()),
            // And so is what was said. Words left in a place are left for
            // whoever comes next, which may be nobody for hours; if a deploy
            // wiped them the whole point of them would be gone.
            Spoken = world.Locations
                .Where(location => location.Spoken.Count > 0)
                .ToDictionary(
                    location => location.Id,
                    location => location.Spoken
                        .Select(words => new WordsState(
                            words.Speaker,
                            words.Text,
                            words.At.ToUnixTimeSeconds()))
                        .ToArray()),
            // And so are the people who got out. This is the only record in the
            // world of anybody succeeding at it, and it would be a poor joke to
            // keep every death across a deploy and lose the escapes.
            Survivors = world.Locations
                .Where(location => location.Survivors.Count > 0)
                .ToDictionary(
                    location => location.Id,
                    location => location.Survivors
                        .Select(survivor => new SurvivorState(
                            survivor.Name,
                            survivor.LifetimeSeconds,
                            survivor.Carried,
                            survivor.At.ToUnixTimeSeconds()))
                        .ToArray()),
            // Only locations the world file gave a monster are recorded. A place
            // that never had one is not mentioned, so writing a creature into it
            // later is not read as "this place is empty".
            Monsters = world.Locations
                .Where(location => location.AuthoredMonster is { Length: > 0 })
                .ToDictionary(
                    location => location.Id,
                    location => location.Monster is { IsAlive: true } monster
                        ? new MonsterState(monster.Name, monster.HitPoints)
                        : null),
            ClearedAt = world.Locations
                .Where(location => location.AuthoredMonster is { Length: > 0 } && location.ClearedAt is not null)
                .ToDictionary(
                    location => location.Id,
                    location => location.ClearedAt!.Value.ToUnixTimeSeconds())
        };
    }

    /// <summary>
    /// Carries a running world's state onto a freshly loaded one.
    ///
    /// Where the world file has been rewritten since the snapshot was taken, the
    /// file wins: whoever wrote it spoke more recently than whatever happened in
    /// the world. That is what <paramref name="previouslyAuthored"/> is for —
    /// without it, a description changed by an interaction would silently swallow
    /// every later rewrite of that room.
    /// </summary>
    public static void Apply(this WorldSnapshot snapshot, World world,
                             IReadOnlyDictionary<int, string>? previouslyAuthored)
    {
        if (previouslyAuthored is not null)
        {
            foreach (var (locationId, authored) in previouslyAuthored)
            {
                if (world.AuthoredDescriptions.TryGetValue(locationId, out var current)
                    && current != authored)
                {
                    snapshot.LocationDescriptions.Remove(locationId);
                }
            }
        }

        snapshot.Apply(world);
    }

    public static void Apply(this WorldSnapshot snapshot, World world)
    {
        world.Conditions.Clear();

        foreach (var condition in snapshot.Conditions)
        {
            world.Conditions.Add(condition);
        }

        foreach (var id in snapshot.DisabledInteractions)
        {
            if (world.FindInteraction(id) is { } interaction) interaction.DisabledForWorld = true;
        }

        foreach (var id in snapshot.EnabledInteractions)
        {
            if (world.FindInteraction(id) is { } interaction) interaction.DisabledForWorld = false;
        }

        foreach (var (locationId, description) in snapshot.LocationDescriptions)
        {
            if (world.FindLocation(locationId) is { } location) location.Description = description;
        }

        foreach (var location in world.Locations)
        {
            location.Items.Clear();
            location.Dead.Clear();
            location.Spoken.Clear();
            location.Survivors.Clear();
        }

        foreach (var (locationId, items) in snapshot.GroundItems)
        {
            if (world.FindLocation(locationId) is not { } location)
            {
                continue;
            }

            foreach (var name in items)
            {
                if (world.CreateItem(name) is { } item) location.Items.Add(item);
            }
        }

        foreach (var (locationId, dead) in snapshot.Dead)
        {
            if (world.FindLocation(locationId) is not { } location)
            {
                continue;
            }

            foreach (var state in dead)
            {
                location.Remember(new Fallen(
                    state.Name,
                    state.Cause,
                    state.LifetimeSeconds,
                    state.Carried,
                    DateTimeOffset.FromUnixTimeSeconds(state.At)));
            }
        }

        foreach (var (locationId, spoken) in snapshot.Spoken)
        {
            if (world.FindLocation(locationId) is not { } location)
            {
                continue;
            }

            foreach (var state in spoken)
            {
                location.Keep(new Words(
                    state.Speaker,
                    state.Text,
                    DateTimeOffset.FromUnixTimeSeconds(state.At)));
            }
        }

        foreach (var (locationId, survivors) in snapshot.Survivors)
        {
            if (world.FindLocation(locationId) is not { } location)
            {
                continue;
            }

            foreach (var state in survivors)
            {
                location.RecordEscape(new Survivor(
                    state.Name,
                    state.LifetimeSeconds,
                    state.Carried,
                    DateTimeOffset.FromUnixTimeSeconds(state.At)));
            }
        }

        // A location absent from the snapshot keeps whatever the world file gave it,
        // so a monster newly written into a place survives the overlay.
        foreach (var (locationId, state) in snapshot.Monsters)
        {
            if (world.FindLocation(locationId) is not { } location)
            {
                continue;
            }

            // The world file may have changed which creature belongs here. If it
            // has, the new one stands, rather than the old one's corpse persisting.
            if (state is not null && !string.Equals(state.Name, location.AuthoredMonster,
                    StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }

            if (state is null)
            {
                if (snapshot.ClearedAt.TryGetValue(locationId, out var cleared))
                {
                    location.ClearedAt = DateTimeOffset.FromUnixTimeSeconds(cleared);
                }

                location.Monster = null;
                continue;
            }

            if (world.SpawnMonster(state.Name) is { } monster)
            {
                monster.HitPoints = Math.Clamp(state.HitPoints, 0, monster.MaxHitPoints);
                location.Monster = monster.IsAlive ? monster : null;
            }
        }
    }
}

using Og.Core.Model;

namespace Og.Core.Runtime;

/// <summary>
/// The world's single mutator. All commands funnel through <see cref="HandleInput"/>
/// on one thread; nothing else writes world state.
/// </summary>
public sealed class GameEngine
{
    private readonly Random _random;
    private readonly IEventSink _events;
    private readonly CommandRegistry _commands = new();
    private readonly List<Session> _sessions = [];

    public World World { get; private set; }

    /// <summary>
    /// Puts a different world under the people already in it.
    ///
    /// Safe because nothing holds on to a place: characters carry a location
    /// number and every command resolves it afresh. Anyone standing somewhere the
    /// new world does not have is moved to where people begin.
    ///
    /// Must be called on the world's own thread, with nothing mid-command.
    /// </summary>
    public IReadOnlyList<Session> SwapWorld(World replacement)
    {
        World = replacement;

        var displaced = new List<Session>();

        foreach (var session in _sessions)
        {
            if (World.FindLocation(session.CurrentLocationId) is not null)
            {
                continue;
            }

            session.CurrentLocationId = World.SpawnLocation;
            displaced.Add(session);
        }

        return displaced;
    }

    /// <summary>Sessions of living characters only. The dead are removed immediately.</summary>
    public IReadOnlyList<Session> Sessions => _sessions;

    /// <summary>
    /// Raised when a character's life is over and its session must be closed out.
    /// There are two ways that happens — killed, or walked out of the door alive —
    /// and from the host's point of view they are the same: this person does not
    /// come back, and whoever is at the other end may name somebody new.
    /// </summary>
    public event Action<Session>? CharacterDied;

    public GameEngine(World world, IEventSink events, int seed = 0)
    {
        World = world;
        _events = events;
        _random = seed == 0 ? new Random() : new Random(seed);
        DefaultCommands.Register(_commands);
    }

    public void Emit(GameEvent gameEvent) => _events.Emit(gameEvent);

    // ---- life and death -----------------------------------------------------

    /// <summary>Births a new character into the world at the spawn location.</summary>
    public Session Enter(string name, IOutputSink output)
    {
        var character = new Character(Guid.NewGuid().ToString("n")[..12], name)
        {
            CurrentLocationId = World.SpawnLocation
        };

        GiveStartingItems(character);

        var session = new Session(character, output);
        _sessions.Add(session);

        Emit(GameEvent.For(session, EventType.CharacterBorn, ("name", name)));
        Emit(GameEvent.For(session, EventType.Arrived));

        BroadcastToLocation(session.CurrentLocationId, $"{name} appears.", except: session);
        session.Write(DescribeCurrentLocation(session));

        return session;
    }

    /// <summary>Returns an existing character to the world, exactly as it was left.</summary>
    public Session Resume(Character character, IOutputSink output)
    {
        if (character.IsDead)
        {
            throw new InvalidOperationException($"Character {character.Id} is dead and cannot return.");
        }

        if (character.HasEscaped)
        {
            throw new InvalidOperationException($"Character {character.Id} left this world and cannot return.");
        }

        if (World.FindLocation(character.CurrentLocationId) is null)
        {
            character.CurrentLocationId = World.SpawnLocation;
        }

        var session = new Session(character, output);
        _sessions.Add(session);

        Emit(GameEvent.For(session, EventType.Arrived));
        BroadcastToLocation(session.CurrentLocationId, $"{character.Name} appears.", except: session);
        session.Write(DescribeCurrentLocation(session));

        return session;
    }

    /// <summary>A living character leaving the world without dying — a disconnect.</summary>
    public void Depart(Session session)
    {
        if (!_sessions.Remove(session))
        {
            return;
        }

        Emit(GameEvent.For(session, EventType.Departed));
        BroadcastToLocation(session.CurrentLocationId, $"{session.Character.Name} fades away.", except: session);
    }

    /// <summary>
    /// The way out, taken.
    ///
    /// This is the only end to a life here that is not death, and until now it was
    /// not an end at all: the door said congratulations and the character went on
    /// standing in front of it with nothing left to do. The first person ever to
    /// open it asked, in as many words, "what happens now?" — and the honest
    /// answer was nothing. So now it finishes them, the way dying does: they go
    /// through, alive, keeping everything they carried, and they do not come back.
    /// What they walked out with is written into the record, because in a world
    /// where every life ends that is the whole of what anyone achieves.
    ///
    /// And the door keeps them. Twelve people got out before this was written and
    /// the door they opened did not know any of their names; see
    /// <see cref="Survivor"/>.
    /// </summary>
    public void Escape(Session session)
    {
        var character = session.Character;
        var location = CurrentLocation(session);
        var manifest = Manifest(character.AllPossessions().Select(item => item.Name));
        var lifetime = (int)(DateTimeOffset.UtcNow - character.BornAt).TotalSeconds;

        character.MarkEscaped(manifest);

        // Before the session goes. The door remembers this the way a floor
        // remembers whoever died on it — a name, how long, and what went with them.
        location?.RecordEscape(new Survivor(character.Name, lifetime, manifest, DateTimeOffset.UtcNow));

        Emit(GameEvent.For(session, EventType.Escaped,
            ("name", character.Name),
            ("lifetime_seconds", lifetime.ToString()),
            ("carried_out", manifest)));

        BroadcastToWorld(
            $"Somewhere far above, a door opens and closes again. {character.Name} is out.",
            except: session);

        session.Write(
            "The key turns over hard, and the door gives.\n\n" +
            "Beyond it is daylight, and cold air, and country this world does not know the shape of. " +
            $"You walk out into it carrying {manifest}, after {Spent(lifetime)} underground.\n\n" +
            $"That is the end of {character.Name} — the only ending here that is not dying. " +
            "Almost everything that has ever left this place left it on its back. You did not.\n\n" +
            "The door keeps your name on this side of it. Whoever stands here next will be told "
            + "that you came through, how long it took you, and what you were carrying when you did.");

        _sessions.Remove(session);
        CharacterDied?.Invoke(session);
    }

    private static string Spent(int seconds) => seconds switch
    {
        < 120 => "barely a minute",
        < 3600 => $"{Math.Max(2, seconds / 60)} minutes",
        < 7200 => "an hour",
        _ => $"{seconds / 3600} hours"
    };

    /// <summary>
    /// A pile of things said the way a person would say it.
    ///
    /// Every list this world shows anybody — what is lying on the floor, what a
    /// corpse spilled, and above all the manifest a character walks out of the
    /// door carrying — was a raw enumeration of item names with the duplicates
    /// left in. Wick escaped carrying "dagger, key, dagger, key, tin whistle,
    /// shortsword, leather armor". That is the last sentence anybody ever reads
    /// here, the summing-up of an entire life, and it read like a database dump.
    ///
    /// So: like things are counted together and the list is joined with an "and".
    /// Nothing about the world changes. It is only that the record of what someone
    /// managed is now in a language.
    /// </summary>
    public static string Manifest(IEnumerable<string> names)
    {
        var grouped = names
            .GroupBy(name => name, StringComparer.OrdinalIgnoreCase)
            .Select(group => group.Count() == 1
                ? group.Key
                : $"{Counted(group.Count())} {Plural(group.Key)}")
            .ToList();

        return grouped.Count == 0 ? "nothing at all" : Join(grouped);
    }

    private static string Counted(int count) => count switch
    {
        2 => "two",
        3 => "three",
        4 => "four",
        5 => "five",
        6 => "six",
        7 => "seven",
        8 => "eight",
        9 => "nine",
        _ => count.ToString()
    };

    private static string Capitalised(string word) =>
        word.Length == 0 ? word : char.ToUpperInvariant(word[0]) + word[1..];

    private static string Plural(string name) =>
        name.EndsWith('s') || name.EndsWith('x') ||
        name.EndsWith("ch", StringComparison.OrdinalIgnoreCase) ||
        name.EndsWith("sh", StringComparison.OrdinalIgnoreCase)
            ? name + "es"
            : name + "s";

    /// <summary>
    /// The character is marked dead, drops everything it carried where it fell,
    /// and its session ends. The place keeps a record of them.
    /// </summary>
    public void Die(Session session, string cause)
    {
        var character = session.Character;
        var location = CurrentLocation(session);

        character.MarkDead(cause);

        var dropped = character.AllPossessions().ToList();
        var spilled = Manifest(dropped.Select(item => item.Name));
        var lifetime = (int)(DateTimeOffset.UtcNow - character.BornAt).TotalSeconds;

        if (location is not null)
        {
            location.Items.AddRange(dropped);

            // The floor keeps them. Not the character — that is finished and
            // nothing may reach back into it — only what the place saw: a name,
            // what did it, how long they lasted, and what fell.
            location.Remember(new Fallen(character.Name, cause, lifetime, spilled, DateTimeOffset.UtcNow));
        }

        character.Inventory.Clear();
        character.Weapon = null;
        character.Armor = null;

        Emit(GameEvent.For(session, EventType.Death,
            ("cause", cause),
            ("name", character.Name),
            ("lifetime_seconds", lifetime.ToString()),
            ("dropped", spilled)));

        BroadcastToLocation(session.CurrentLocationId,
            $"{character.Name} is killed by {cause}.", except: session);

        if (dropped.Count > 0)
        {
            BroadcastToLocation(session.CurrentLocationId,
                $"Their belongings fall to the ground: {spilled}.",
                except: session);
        }

        session.Write($"\nYou are killed by {cause}.\n\nThat is the end of {character.Name}.");

        _sessions.Remove(session);
        CharacterDied?.Invoke(session);
    }

    // ---- the dead ---------------------------------------------------------------

    /// <summary>
    /// What a place says about the people who have died on it, or null where
    /// nobody has.
    ///
    /// Every room in this world describes itself in exactly the sentence it was
    /// written with, whatever has happened in it since. The Deep Passage has
    /// killed four people and still opens with "far ahead, something shifts" —
    /// the same words it used before anybody had ever been down there. This is
    /// the one thing a place can now say that it was not authored with, and it
    /// is the only way one life here is ever visible to another.
    ///
    /// It names names, because the names are the whole of it, and it says out
    /// loud that they can be looked at — the lesson of the troll's bed being
    /// that a thing nobody is told about is a thing nobody finds.
    /// </summary>
    public static string? Remembrance(Location location)
    {
        var dead = location.Dead;

        if (dead.Count == 0)
        {
            return null;
        }

        if (dead.Count == 1)
        {
            return $"{dead[0].Name} died here, killed by {dead[0].Cause}. "
                + $"Look at {dead[0].Name} and this place will tell you who that was.";
        }

        var causes = dead
            .Select(fallen => fallen.Cause)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();

        var shared = causes.Count == 1 ? $" All of them killed by {causes[0]}." : string.Empty;
        var counted = Capitalised(Counted(dead.Count));

        if (dead.Count <= 4)
        {
            var names = dead.Select(fallen => fallen.Name).ToList();

            return $"{counted} people have died here: {Join(names)}.{shared} "
                + "Any of them can be looked at by name.";
        }

        var latest = dead.Skip(dead.Count - 3).Select(fallen => fallen.Name).ToList();

        return $"{counted} people have died here.{shared} "
            + $"The last of them were {Join(latest)}. Any of them can be looked at by name.";
    }

    /// <summary>What one of a place's dead was, told to somebody who asked by name.</summary>
    public static string Describe(Fallen fallen) =>
        $"{fallen.Name}, who lasted {Spent(fallen.LifetimeSeconds)} down here before {fallen.Cause} killed them. "
        + (string.Equals(fallen.Carried, "nothing at all", StringComparison.OrdinalIgnoreCase)
            ? "They had nothing on them at the end."
            : $"What they had fell where they fell: {fallen.Carried}. Whether any of it is still on this floor is another question.")
        + $"\n\nThere is no coming back from this, for them or for you. {fallen.Name} got exactly one life here, the same as you have."
        + "\n\nWhatever you have to say to them, this is the place to say it: whisper it, or carve it. It will still be here when you are not.";

    // ---- the ones who got out -------------------------------------------------------

    /// <summary>
    /// What a door says about the people who have gone out through it, or null
    /// where nobody has.
    ///
    /// The mirror of <see cref="Remembrance"/>, and the reason it exists: this
    /// world keeps an exact and permanent account of everyone it has killed and
    /// kept nothing whatever about anyone who beat it. Standing at the door with
    /// no key, the only thing the world could tell you was how many strangers had
    /// died on the way here. That is a true picture of the place and a badly
    /// incomplete one.
    ///
    /// The shortest time is named on purpose. It is the one number here that
    /// reads as a dare.
    /// </summary>
    public static string? WhoGotOut(Location location)
    {
        var survivors = location.Survivors;

        if (survivors.Count == 0)
        {
            return null;
        }

        if (survivors.Count == 1)
        {
            return $"One person has gone out through this door alive: {survivors[0].Name}, "
                + $"after {Spent(survivors[0].LifetimeSeconds)} down here. "
                + $"Look at {survivors[0].Name} and the door will tell you what they took with them.";
        }

        var quickest = survivors.MinBy(survivor => survivor.LifetimeSeconds)!;
        var latest = survivors.Skip(Math.Max(0, survivors.Count - 3))
            .Select(survivor => survivor.Name)
            .ToList();

        return $"{Capitalised(Counted(survivors.Count))} people have gone out through this door alive. "
            + $"The last of them were {Join(latest)}; the quickest was {quickest.Name}, "
            + $"who was down here {Spent(quickest.LifetimeSeconds)}. "
            + "Any of them can be looked at by name.";
    }

    /// <summary>What one of the people who got out was, told to somebody who asked by name.</summary>
    public static string Describe(Survivor survivor) =>
        $"{survivor.Name}, who was down here {Spent(survivor.LifetimeSeconds)} and then opened this door and walked out. "
        + (string.Equals(survivor.Carried, "nothing at all", StringComparison.OrdinalIgnoreCase)
            ? "They took nothing out with them at all."
            : $"What went out with them: {survivor.Carried}. None of it is coming back.")
        + "\n\nThey are not dead and they are not here. There is no third thing to know about them — "
        + "this world does not follow anybody out.";

    // ---- what was said here ------------------------------------------------------

    /// <summary>
    /// What has been left written or spoken in a place, or null where nothing has.
    ///
    /// See <see cref="Words"/> for the person this exists because of.
    /// </summary>
    public static string? WhatWasSaid(Location location)
    {
        var spoken = location.Spoken;

        if (spoken.Count == 0)
        {
            return null;
        }

        var lines = spoken.Select(words => $"  {words.Speaker}: \"{words.Text}\"");

        return (spoken.Count == 1
                ? "Somebody left words in this place.\n"
                : "People have left words in this place.\n")
            + string.Join("\n", lines);
    }

    /// <summary>
    /// Somebody saying something to a place rather than to a person.
    ///
    /// Said out loud to anyone standing there, because they are standing there —
    /// and then kept, because almost nobody ever is. There is no reply and no
    /// delivery: whoever reads it later gets a name and a sentence and nothing
    /// else, and the name is very likely already dead.
    /// </summary>
    public void LeaveWords(Session session, string text)
    {
        var clipped = Words.Clip(text);

        if (clipped.Length == 0)
        {
            session.Write("You do not say anything.");
            return;
        }

        var location = CurrentLocation(session);

        if (location is null)
        {
            session.Write("There is nowhere here to leave that.");
            return;
        }

        location.Keep(new Words(session.Character.Name, clipped, DateTimeOffset.UtcNow));

        BroadcastToLocation(location.Id,
            $"{session.Character.Name} leaves words here: \"{clipped}\"", except: session);

        // Who is actually standing here decides how this reads. Telling somebody
        // "nobody is listening" with another player three feet away is a small
        // lie, and this world's whole case for itself is that it does not tell
        // them.
        var listening = PlayersAt(location.Id).Count(other => other != session);

        session.Write($"You leave it here, where it was meant: \"{clipped}\"\n\n"
            + (listening > 0
                ? "Whoever is standing here heard you. It will still be here when they are not."
                : "Nobody is listening. It will still be here when you are not."));

        Emit(GameEvent.For(session, EventType.Speech, ("mode", "left"), ("text", clipped)));
    }

    private void GiveStartingItems(Character character)
    {
        foreach (var name in World.StartingItems)
        {
            if (World.CreateItem(name) is not { } item)
            {
                continue;
            }

            switch (item.Kind)
            {
                case ItemKind.Weapon when character.Weapon is null:
                    character.Weapon = item;
                    break;

                case ItemKind.Armor when character.Armor is null:
                    character.Armor = item;
                    break;

                default:
                    character.Inventory.Add(item);
                    break;
            }
        }
    }

    public Location? CurrentLocation(Session session) => World.FindLocation(session.CurrentLocationId);

    // ---- input ---------------------------------------------------------------

    public void HandleInput(Session session, string rawCommand)
    {
        if (string.IsNullOrWhiteSpace(rawCommand) || session.Character.IsFinished)
        {
            return;
        }

        var raw = rawCommand.Trim();
        var command = TriggerMatcher.Normalize(rawCommand);

        Emit(GameEvent.For(session, EventType.Command, ("text", raw)));

        var result = _commands.Execute(this, session, command, raw);

        if (result.Status == CommandStatus.Done)
        {
            return;
        }

        // A verb that came to nothing still carries on to the place the player is
        // standing in: the room may know what the engine does not.
        if (TryInteractions(session, command))
        {
            return;
        }

        // Nothing anywhere had an answer. Recorded rather than discarded, with
        // whatever the engine was going to say about it.
        Emit(GameEvent.For(session, EventType.UnparsedCommand,
            ("text", raw),
            ("kind", result.Status == CommandStatus.Futile ? "no effect" : "unrecognised"),
            ("refusal", result.Message ?? "")));

        session.Write(result.Message ?? "Nothing happens.");
    }

    private bool TryInteractions(Session session, string command)
    {
        var location = CurrentLocation(session);

        if (location is null)
        {
            return false;
        }

        // Snapshot: an action may enable or disable interactions mid-iteration.
        foreach (var interaction in location.Interactions.ToArray())
        {
            if (!interaction.IsEligible(World, session) || !interaction.MatchesTrigger(command))
            {
                continue;
            }

            Emit(GameEvent.For(session, EventType.InteractionFired,
                ("interaction", interaction.Id ?? "(anonymous)"),
                ("command", command)));

            foreach (var action in interaction.Actions)
            {
                Execute(session, action);
            }

            if (interaction.Once && interaction.Id is not null)
            {
                session.Character.FiredInteractions.Add(interaction.Id);
            }

            return true;
        }

        return false;
    }

    // ---- interaction actions --------------------------------------------------

    private void Execute(Session session, WorldAction action)
    {
        switch (action.Kind)
        {
            case ActionKind.Describe:
                session.Write(action.FirstParameter);
                break;

            case ActionKind.AddItems:
                foreach (var name in action.Parameters)
                {
                    if (World.CreateItem(name) is { } item)
                    {
                        session.Character.Inventory.Add(item);
                        session.Write($"You received {item.Name}.");
                        Emit(GameEvent.For(session, EventType.ItemPickedUp, ("item", item.Name)));
                    }
                }
                break;

            case ActionKind.RemoveItems:
                foreach (var name in action.Parameters)
                {
                    if (session.Character.FindItem(name) is { } item)
                    {
                        session.Character.Inventory.Remove(item);
                        Emit(GameEvent.For(session, EventType.ItemDropped, ("item", item.Name)));
                    }
                }
                break;

            case ActionKind.ChangeLocation:
                MoveTo(session, action.FirstParameterAsInt);
                break;

            case ActionKind.SetLocationDescription:
                if (World.FindLocation(action.FirstParameterAsInt) is { } target
                    && action.Parameters.Length > 1)
                {
                    target.Description = action.Parameters[1];
                }
                break;

            case ActionKind.EnableInteraction:
                SetInteractionDisabled(session, action, disabled: false);
                break;

            case ActionKind.DisableInteraction:
                SetInteractionDisabled(session, action, disabled: true);
                break;

            case ActionKind.AddCondition:
                ConditionSet(session, action.Scope).Add(action.FirstParameter);
                break;

            case ActionKind.RemoveCondition:
                ConditionSet(session, action.Scope).Remove(action.FirstParameter);
                break;

            case ActionKind.Heal:
                Mend(session, action);
                break;
        }
    }

    /// <summary>
    /// A place putting a character back together. "full" or a number of hit
    /// points; never past the maximum, and never a negative.
    /// </summary>
    private void Mend(Session session, WorldAction action)
    {
        var character = session.Character;
        var missing = character.MaxHitPoints - character.HitPoints;

        var wanted = action.Parameters.Length == 0
            || string.Equals(action.FirstParameter, "full", StringComparison.OrdinalIgnoreCase)
                ? missing
                : action.FirstParameterAsInt;

        var healed = Math.Clamp(wanted, 0, missing);
        character.HitPoints += healed;

        session.Write(healed > 0
            ? $"You are mended. HP: {character.HitPoints}/{character.MaxHitPoints}"
            : $"You had nothing that needed mending. HP: {character.HitPoints}/{character.MaxHitPoints}");

        Emit(GameEvent.For(session, EventType.Healed, ("amount", healed.ToString())));
    }

    private HashSet<string> ConditionSet(Session session, Scope scope) =>
        scope == Scope.World ? World.Conditions : session.Character.Conditions;

    private void SetInteractionDisabled(Session session, WorldAction action, bool disabled)
    {
        var id = action.FirstParameter;

        if (action.Scope == Scope.Player)
        {
            if (disabled)
            {
                session.Character.DisabledInteractions.Add(id);
            }
            else
            {
                session.Character.DisabledInteractions.Remove(id);
            }

            return;
        }

        if (World.FindInteraction(id) is { } interaction)
        {
            interaction.DisabledForWorld = disabled;
        }
    }

    // ---- movement --------------------------------------------------------------

    public void MoveTo(Session session, int locationId)
    {
        var destination = World.FindLocation(locationId);

        if (destination is null)
        {
            Emit(GameEvent.For(session, EventType.BlockedMovement, ("target", locationId.ToString())));
            session.Write("You can't go that way.");
            return;
        }

        var from = session.CurrentLocationId;

        BroadcastToLocation(from, $"{session.Character.Name} leaves.", except: session);
        session.CurrentLocationId = destination.Id;
        BroadcastToLocation(destination.Id, $"{session.Character.Name} arrives.", except: session);

        Emit(GameEvent.For(session, EventType.Movement,
            ("from", from.ToString()), ("to", destination.Id.ToString())));

        session.Write(DescribeCurrentLocation(session));
    }

    // ---- combat ------------------------------------------------------------------

    public void Attack(Session session)
    {
        var location = CurrentLocation(session);

        if (location?.Monster is not { } monster || !monster.IsAlive)
        {
            session.Write("There is nothing to attack here.");
            return;
        }

        var character = session.Character;
        var attackRoll = _random.Next(1, 21) + character.AttackStrength;
        var damage = _random.Next(1, character.AttackDice + 1) + character.AttackStrength;

        if (monster.ReceiveAttack(attackRoll, damage))
        {
            // What you did, and what it did to them. "You hit!" on its own left a
            // person five exchanges from a kill unable to tell a first blow from a
            // last one, and the whole shape of a fight here is deciding whether to
            // press on or walk out.
            session.Write(monster.WoundLook() is { } hurt
                ? $"You hit the {monster.Name} for {damage}. It is {hurt}."
                : $"You hit the {monster.Name} for {damage}.");

            Emit(GameEvent.For(session, EventType.Combat,
                ("target", monster.Name), ("result", "hit"), ("damage", damage.ToString()),
                ("target_hp", monster.HitPoints.ToString())));

            if (!monster.IsAlive)
            {
                session.Write($"The {monster.Name} has died.");
                BroadcastToLocation(location.Id, $"{character.Name} slays the {monster.Name}.", except: session);

                location.Items.AddRange(monster.Inventory);
                Emit(GameEvent.For(session, EventType.MonsterSlain, ("monster", monster.Name)));
                location.Monster = null;
                location.ClearedAt = DateTimeOffset.UtcNow;

                if (location.Items.Count > 0)
                {
                    session.Write($"On the ground: {Manifest(location.Items.Select(item => item.Name))}.");
                }

                return;
            }
        }
        else
        {
            session.Write("You missed!");
            Emit(GameEvent.For(session, EventType.Combat, ("target", monster.Name), ("result", "miss")));
        }

        var monsterRoll = _random.Next(1, 21) + monster.AttackStrength;
        var monsterDamage = _random.Next(1, monster.AttackDice + 1) + monster.AttackStrength;

        // The other half of the fight. Without this the record shows only the
        // swings a person took and never what was done back to them, and a death
        // cannot be read afterwards.
        if (character.ReceiveAttack(monsterRoll, monsterDamage))
        {
            Emit(GameEvent.Against(session, EventType.Combat,
                ("attacker", monster.Name), ("target", character.Name), ("result", "hit"),
                ("damage", monsterDamage.ToString()), ("target_hp", character.HitPoints.ToString())));

            session.Write($"You were hit! HP: {character.HitPoints}/{character.MaxHitPoints}");

            if (!character.IsAlive)
            {
                Die(session, $"a {monster.Name}");
            }
            else
            {
                WarnIfDying(session, monster);
            }
        }
        else
        {
            Emit(GameEvent.Against(session, EventType.Combat,
                ("attacker", monster.Name), ("target", character.Name), ("result", "miss"))); 

            session.Write($"The {monster.Name} missed!");
        }
    }

    /// <summary>
    /// Said whenever a character is standing inside the range of a single blow.
    ///
    /// Two true things about this world are worth more here than anywhere else and
    /// neither was ever stated: nothing pursues you out of a room, and a monster
    /// does not mend while you can. Everyone who has died to the troll so far died
    /// with an untouched potion on them and three rooms of open passage at their
    /// back. They were not beaten. They did not know they were allowed to leave.
    ///
    /// The threshold is the creature's own hardest hit, not a fraction of the
    /// character. It used to be a third, and that was wrong in the only case that
    /// matters: a cave troll swings for up to eleven, so a character on seven hit
    /// points was already one roll from dead and heard nothing. Marrow died in
    /// exactly that gap — seven, then nothing, then killed, with the key to the
    /// door already in his pocket. A warning that arrives after the danger does
    /// is not a warning. So it is the monster in front of you that decides when
    /// you are told, because it is the monster in front of you that decides.
    /// </summary>
    private static void WarnIfDying(Session session, Monster monster)
    {
        var character = session.Character;
        var hardestBlow = monster.AttackDice + monster.AttackStrength;

        if (character.HitPoints > hardestBlow)
        {
            return;
        }

        session.Write(
            $"You are badly hurt — the next one the {monster.Name} lands can kill you outright. " +
            "Nothing here follows you out of a room, and nothing here mends itself while you are gone.");

        // The thing most worth saying to somebody about to throw away the only
        // ending this world has that is not dying.
        if (character.HasKey)
        {
            session.Write(
                "You are carrying the key. Whatever you are still down here for, "
                + "it is worth less than walking out with it.");
        }
    }

    /// <summary>
    /// Brings back creatures whose time has passed. Called on the world's own
    /// thread, so nothing else is mid-way through reading the map.
    /// </summary>
    public void Repopulate()
    {
        foreach (var location in World.Repopulate(DateTimeOffset.UtcNow))
        {
            Emit(new GameEvent(Actor.Engine, EventType.MonsterReturned, null, location.Id,
                new Dictionary<string, string> { ["monster"] = location.Monster!.Name }));

            BroadcastToLocation(location.Id,
                $"Something moves. {location.Monster!.Description}");
        }
    }

    // ---- description ----------------------------------------------------------------

    public string DescribeCurrentLocation(Session session)
    {
        var location = CurrentLocation(session);

        if (location is null)
        {
            return "You are nowhere.";
        }

        // How the place reads to this person, now — which is not necessarily how
        // it was authored. See World.DescriptionFor.
        var parts = new List<string> { World.DescriptionFor(session, location) };

        if (location.Monster is { IsAlive: true } monster)
        {
            parts.Add(monster.Description);

            // The keystone of the only tactic this world has. A creature that has
            // been fought before looks it, and is told plainly not to be mending,
            // because the one strong move available to anybody here — hit it, walk
            // back to the fire, sleep, return — is worth nothing if you cannot see
            // that last time counted.
            if (monster.WoundLook() is { } wounded)
            {
                parts.Add($"The {monster.Name} is {wounded}, and carrying every wound "
                    + "it has been given. It has not mended, and it will not.");
            }
        }

        // The dead come before the loot, because the loot is theirs. Then the ones
        // who got out, because that is the same account read the other way. Then
        // what was said, because it was said to both of them.
        if (Remembrance(location) is { } remembered)
        {
            parts.Add(remembered);
        }

        if (WhoGotOut(location) is { } gotOut)
        {
            parts.Add(gotOut);
        }

        if (WhatWasSaid(location) is { } said)
        {
            parts.Add(said);
        }

        if (location.Items.Count > 0)
        {
            parts.Add($"On the ground: {Manifest(location.Items.Select(item => item.Name))}.");
        }

        var others = PlayersAt(location.Id).Where(other => other != session).ToList();

        if (others.Count > 0)
        {
            parts.Add($"Also here: {string.Join(", ", others.Select(other => other.Character.Name))}.");
        }

        var directions = location.OpenDirections()
            .Select(direction => direction.ToString().ToLowerInvariant())
            .ToList();

        if (directions.Count > 0)
        {
            parts.Add($"There is a passage to the {Join(directions)}.");
        }

        // Going out is final, so it is said plainly before it is done rather than
        // discovered afterwards. Whatever is in your hands goes with you, and
        // whatever you have not done here you will not get back to.
        if (location.IsExit)
        {
            parts.Add(session.Character.HasKey
                ? "You've found the exit! The key you are carrying fits this lock. Open it and you are out — "
                  + "alive, which almost nothing here manages, and not coming back. Whatever you are carrying "
                  + "goes with you; whatever you have left undone stays undone."
                : "You've found the exit! It is locked, and whatever opens it is not in your hands yet. "
                  + "Look at the door itself and it will tell you what it wants and where that is found.");
        }

        return string.Join("\n\n", parts);
    }

    private static string Join(IReadOnlyList<string> values) => values.Count switch
    {
        1 => values[0],
        2 => $"{values[0]} and {values[1]}",
        _ => $"{string.Join(", ", values.Take(values.Count - 1))}, and {values[^1]}"
    };

    // ---- broadcast --------------------------------------------------------------------

    public IEnumerable<Session> PlayersAt(int locationId) =>
        _sessions.Where(session => session.CurrentLocationId == locationId);

    public void BroadcastToLocation(int locationId, string message, Session? except = null)
    {
        foreach (var session in PlayersAt(locationId).ToArray())
        {
            if (session != except)
            {
                session.Write(message);
            }
        }
    }

    public void BroadcastToWorld(string message, Session? except = null)
    {
        foreach (var session in _sessions.ToArray())
        {
            if (session != except)
            {
                session.Write(message);
            }
        }
    }
}

using Og.Core.Model;

namespace Og.Core.Runtime;

/// <summary>
/// The verbs the engine knows. A handler returns Done only when something
/// actually happened; when it recognises the words but can do nothing with them
/// it returns Futile, and the command carries on to the place the player is in.
///
/// Anything that names a thing — an item to take, a creature to hit — looks it up
/// through <see cref="Naming.Strip"/>, so "drink the potion" and "drink potion"
/// are the same sentence. Speech does not: what someone says is passed through
/// exactly as they typed it, articles and all.
/// </summary>
public static class DefaultCommands
{
    public static void Register(CommandRegistry registry)
    {
        RegisterMovement(registry);
        RegisterObservation(registry);
        RegisterInventory(registry);
        RegisterGiving(registry);
        RegisterCombat(registry);
        RegisterRest(registry);
        RegisterSpeech(registry);
    }

    private static void RegisterMovement(CommandRegistry registry)
    {
        Move(Direction.North, "go north", "north", "n");
        Move(Direction.East, "go east", "east", "e");
        Move(Direction.South, "go south", "south", "s");
        Move(Direction.West, "go west", "west", "w");

        void Move(Direction direction, params string[] forms) =>
            registry.RegisterExact((engine, session, _) =>
            {
                var location = engine.CurrentLocation(session);

                if (location is null)
                {
                    return CommandResult.NotHandled;
                }

                var target = location.Exit(direction);

                // A wall is worth knowing about, but the room may still answer.
                if (target <= 0)
                {
                    engine.Emit(GameEvent.For(session, EventType.BlockedMovement,
                        ("direction", direction.ToString().ToLowerInvariant())));

                    return CommandResult.Futile("You can't go that way.");
                }

                engine.MoveTo(session, target);
                return CommandResult.Done();
            }, forms);
    }

    /// <summary>
    /// The words people use for a place's dead all together rather than for one
    /// of them by name. Found by playing: a character was told plainly that Sable
    /// had died on that floor and the next thing typed was "look at the bodies",
    /// which the world answered with "You don't see a bodies here."
    /// </summary>
    private static bool IsAskingAboutTheDead(string wanted) =>
        wanted is "bodies" or "body" or "dead" or "dead body" or "dead bodies"
            or "dead people" or "corpse" or "corpses" or "remains" or "fallen"
            or "grave" or "graves" or "who died" or "who has died";

    /// <summary>The words people use for what has been left written in a place.</summary>
    private static bool IsAskingAboutWords(string wanted) =>
        wanted is "words" or "writing" or "writings" or "message" or "messages"
            or "inscription" or "inscriptions" or "note" or "notes" or "carving"
            or "carvings" or "graffiti" or "what was said";

    /// <summary>
    /// The words people use for the people who got out. The other half of asking
    /// a place who has been here — and until now the half it could not answer.
    /// </summary>
    private static bool IsAskingAboutTheEscaped(string wanted) =>
        wanted is "survivors" or "survivor" or "escaped" or "the escaped"
            or "who got out" or "who has got out" or "who escaped" or "who left"
            or "who made it" or "roll" or "the roll" or "names" or "the names"
            or "record" or "the record" or "tally";

    /// <summary>
    /// A place's dead, asked about collectively. Where nobody has died the answer
    /// is Futile rather than Done, so the room still gets its turn: a floor with
    /// no dead on it may well have something else to say about being searched.
    /// </summary>
    private static CommandResult TheDeadHere(GameEngine engine, Session session, string argument)
    {
        var wanted = Naming.Strip(argument);

        if (IsAskingAboutWords(wanted))
        {
            if (engine.CurrentLocation(session) is { } here
                && GameEngine.WhatWasSaid(here) is { } said)
            {
                session.Write(said);
                return CommandResult.Done();
            }

            return CommandResult.Futile("Nobody has left anything here to read.");
        }

        if (IsAskingAboutTheEscaped(wanted))
        {
            if (engine.CurrentLocation(session) is { } doorway
                && GameEngine.WhoGotOut(doorway) is { } gotOut)
            {
                session.Write(gotOut);
                return CommandResult.Done();
            }

            return CommandResult.Futile("Nobody has ever got out from here.");
        }

        if (!IsAskingAboutTheDead(wanted))
        {
            return CommandResult.NotHandled;
        }

        if (engine.CurrentLocation(session) is { } location
            && GameEngine.Remembrance(location) is { } remembered)
        {
            session.Write(remembered);
            return CommandResult.Done();
        }

        return CommandResult.Futile("Nobody has died here. Not yet.");
    }

    private static void RegisterObservation(CommandRegistry registry)
    {
        registry.RegisterExact((engine, session, _) =>
        {
            session.Write(engine.DescribeCurrentLocation(session));
            return CommandResult.Done();
        }, "look", "look around", "explore", "investigate", "search", "l");

        registry.RegisterExact((_, session, _) =>
        {
            var character = session.Character;
            session.Write($"HP: {character.HitPoints}/{character.MaxHitPoints}");
            return CommandResult.Done();
        }, "health", "hit points", "hp");

        registry.RegisterExact((engine, session, _) =>
        {
            var names = engine.Sessions.Select(other => other.Character.Name).Order();
            session.Write($"Here in this world: {string.Join(", ", names)}");
            return CommandResult.Done();
        }, "who", "players");

        // Asking a place who got out of it. Said on its own, because "who got
        // out" is a whole sentence and nobody prefixes it with a verb. At the
        // door this is the only good news the world has ever been able to give
        // anybody, and before this it could not be asked for at all.
        registry.RegisterExact((engine, session, _) =>
        {
            if (engine.CurrentLocation(session) is { } location
                && GameEngine.WhoGotOut(location) is { } gotOut)
            {
                session.Write(gotOut);
                return CommandResult.Done();
            }

            return CommandResult.Futile("Nobody has ever got out from here.");
        }, "who got out", "who has got out", "who escaped", "who made it", "who survived",
           "survivors", "the survivors", "roll", "the roll");

        // Searching, counting or looting "the bodies" is only ever about the
        // dead. Anything else said with those verbs is handed straight back so
        // the room answers it exactly as it did before.
        registry.RegisterPrefix(TheDeadHere, "search", "check", "count", "read", "loot", "look for");

        // Looking at a thing means looking at any thing you can see: what you
        // carry, what is lying here, whatever is standing in front of you, and
        // whoever died on this floor. Only when none of those is what was meant
        // does the room get its turn.
        registry.RegisterPrefix((engine, session, argument) =>
        {
            var wanted = Naming.Strip(argument);

            if (wanted.Length == 0)
            {
                return CommandResult.Futile("Look at what?");
            }

            if (session.Character.FindItemOrEquipped(wanted) is { } carried)
            {
                session.Write(carried.Description);
                return CommandResult.Done();
            }

            var location = engine.CurrentLocation(session);

            if (location?.Items.FirstOrDefault(item => item.Matches(wanted)) is { } onTheGround)
            {
                session.Write(onTheGround.Description);
                return CommandResult.Done();
            }

            if (location?.Monster is { IsAlive: true } monster && monster.Matches(wanted))
            {
                session.Write(monster.Description);
                return CommandResult.Done();
            }

            var other = engine.PlayersAt(session.CurrentLocationId).FirstOrDefault(candidate =>
                candidate != session &&
                string.Equals(candidate.Character.Name, wanted, StringComparison.OrdinalIgnoreCase));

            if (other is not null)
            {
                var them = other.Character;
                session.Write($"{them.Name}, carrying {(them.Weapon?.Name ?? "nothing")} and wearing {(them.Armor?.Name ?? "nothing")}.");
                return CommandResult.Done();
            }

            // The living are asked about before the dead, so a new arrival of the
            // same name is who you mean. After them: whoever this floor kept.
            if (location?.FindDead(wanted) is { } fallen)
            {
                session.Write(GameEngine.Describe(fallen));
                return CommandResult.Done();
            }

            // And after them, whoever this door let out. A name is only ever on
            // one of the two lists.
            if (location?.FindSurvivor(wanted) is { } survivor)
            {
                session.Write(GameEngine.Describe(survivor));
                return CommandResult.Done();
            }

            if (IsAskingAboutTheDead(wanted) || IsAskingAboutWords(wanted)
                || IsAskingAboutTheEscaped(wanted))
            {
                return TheDeadHere(engine, session, wanted);
            }

            return CommandResult.Futile($"You don't see a {wanted} here.");
        }, "describe", "look at", "examine", "inspect");
    }

    private static void RegisterInventory(CommandRegistry registry)
    {
        registry.RegisterExact((_, session, _) =>
        {
            var character = session.Character;

            session.Write($"Weapon: {character.Weapon?.Name ?? "none equipped"}");
            session.Write($"Armor: {character.Armor?.Name ?? "none equipped"}");
            session.Write(character.Inventory.Count == 0
                ? "Inventory: empty"
                : "Inventory: " + GameEngine.Manifest(character.Inventory.Select(item => item.Name)));

            return CommandResult.Done();
        }, "inventory", "items", "i");

        registry.RegisterPrefix((_, session, argument) =>
        {
            var character = session.Character;
            var wanted = Naming.Strip(argument);
            var item = character.FindItem(wanted);

            if (item is null)
            {
                return CommandResult.Futile($"You aren't carrying a {wanted}.");
            }

            switch (item.Kind)
            {
                case ItemKind.Weapon:
                    if (character.Weapon is { } oldWeapon) character.Inventory.Add(oldWeapon);
                    character.Weapon = item;
                    break;

                case ItemKind.Armor:
                    if (character.Armor is { } oldArmor) character.Inventory.Add(oldArmor);
                    character.Armor = item;
                    break;

                default:
                    return CommandResult.Futile($"You can't equip the {item.Name}.");
            }

            character.Inventory.Remove(item);
            session.Write($"You equipped the {item.Name}.");
            return CommandResult.Done();
        }, "equip", "wield", "wear");

        registry.RegisterPrefix((_, session, argument) =>
        {
            var character = session.Character;
            var wanted = Naming.Strip(argument);
            var item = character.FindItem(wanted);

            if (item is null)
            {
                return CommandResult.Futile($"You aren't carrying a {wanted}.");
            }

            if (item.Kind != ItemKind.Consumable)
            {
                // The room may well know what this thing is for, even though the
                // engine does not.
                return CommandResult.Futile($"Nothing happens when you use the {item.Name}.");
            }

            var healed = Math.Min(item.Definition.HealAmount, character.MaxHitPoints - character.HitPoints);
            character.HitPoints += healed;

            if (item.Definition.ConsumedOnUse)
            {
                character.Inventory.Remove(item);
            }

            session.Write($"You used the {item.Name}. HP: {character.HitPoints}/{character.MaxHitPoints}");
            return CommandResult.Done();
        }, "use", "drink", "eat");

        registry.RegisterPrefix((engine, session, argument) =>
        {
            var location = engine.CurrentLocation(session);
            var wanted = Naming.Strip(argument);

            if (location is null)
            {
                return CommandResult.Futile($"There is no {wanted} here to take.");
            }

            // "take all" is how people empty a floor. Worth knowing, because the
            // floor is where the dead leave everything they had.
            if (string.Equals(wanted, "all", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(wanted, "everything", StringComparison.OrdinalIgnoreCase))
            {
                if (location.Items.Count == 0)
                {
                    return CommandResult.Futile("There is nothing here to take.");
                }

                foreach (var lying in location.Items.ToArray())
                {
                    location.Items.Remove(lying);
                    session.Character.Inventory.Add(lying);
                    session.Write($"You take the {lying.Name}.");
                    engine.BroadcastToLocation(location.Id, $"{session.Character.Name} takes the {lying.Name}.", except: session);
                    engine.Emit(GameEvent.For(session, EventType.ItemPickedUp, ("item", lying.Name)));
                }

                return CommandResult.Done();
            }

            var item = location.Items.FirstOrDefault(candidate => candidate.Matches(wanted));

            if (item is null)
            {
                return CommandResult.Futile($"There is no {wanted} here to take.");
            }

            location.Items.Remove(item);
            session.Character.Inventory.Add(item);
            session.Write($"You take the {item.Name}.");
            engine.BroadcastToLocation(location.Id, $"{session.Character.Name} takes the {item.Name}.", except: session);
            engine.Emit(GameEvent.For(session, EventType.ItemPickedUp, ("item", item.Name)));
            return CommandResult.Done();
        }, "take", "pick up", "get", "grab");

        // Putting a thing down, including the thing in your hand.
        //
        // This used to look only in the pack, so "drop dagger" while holding the
        // dagger answered "You aren't carrying a dagger." — which is both false
        // and, to anyone standing there with it, faintly insulting. A weapon or a
        // jacket you are wearing is still something you own and can set down, so
        // dropping it takes it off you first.
        registry.RegisterPrefix((engine, session, argument) =>
        {
            var location = engine.CurrentLocation(session);
            var character = session.Character;
            var wanted = Naming.Strip(argument);
            var item = character.FindItemOrEquipped(wanted);

            if (location is null || item is null)
            {
                return CommandResult.Futile($"You aren't carrying a {wanted}.");
            }

            if (character.Weapon == item)
            {
                character.Weapon = null;
            }
            else if (character.Armor == item)
            {
                character.Armor = null;
            }
            else
            {
                character.Inventory.Remove(item);
            }

            location.Items.Add(item);
            session.Write($"You drop the {item.Name}.");
            engine.BroadcastToLocation(location.Id, $"{character.Name} drops the {item.Name}.", except: session);
            engine.Emit(GameEvent.For(session, EventType.ItemDropped, ("item", item.Name)));
            return CommandResult.Done();
        }, "drop", "put down", "leave");
    }

    /// <summary>
    /// Holding a thing out to something, or throwing it at it.
    ///
    /// This is the most-asked-for verb in this world's whole history and until
    /// now it did not exist. Three separate people — Tanril, Kaleb, Krasus —
    /// tried to throw a bone, and all three were told "Nothing happens", which
    /// was true and useless. What they were reaching for is the obvious one: a
    /// world where an object can be used on something, rather than only eaten or
    /// worn or swung.
    ///
    /// The engine deliberately does not decide what throwing achieves. It checks
    /// the one thing it is qualified to check — that you have the thing in your
    /// hands — and then returns Futile, which hands the sentence on to the room.
    /// A place that has something to say about being given a bone says it; a
    /// place that has not gives an honest shrug instead of a lie. Nothing is
    /// consumed here, because the interaction that answers has to be able to see
    /// the item still in your inventory in order to know you had it.
    /// </summary>
    private static void RegisterGiving(CommandRegistry registry)
    {
        registry.RegisterExact((_, _, _) => CommandResult.Futile("Throw what?"),
            "throw", "toss", "hurl", "fling", "lob", "give", "offer");

        registry.RegisterPrefix((_, session, argument) =>
        {
            var wanted = NamedThing(argument);

            if (wanted.Length == 0)
            {
                return CommandResult.Futile("Throw what?");
            }

            return session.Character.FindItemOrEquipped(wanted) is { } item
                ? CommandResult.Futile(
                    $"You could throw the {item.Name}, but nothing here would care where it landed.")
                : CommandResult.Futile($"You aren't carrying a {wanted}.");
        }, "throw", "toss", "hurl", "fling", "lob", "give", "offer");
    }

    /// <summary>
    /// The thing being thrown, out of a sentence that may also name what it is
    /// being thrown at. "throw the bone to the troll" is about a bone.
    /// </summary>
    private static string NamedThing(string argument)
    {
        var spoken = Naming.Strip(argument);

        foreach (var joiner in (string[])[" at ", " to ", " toward ", " towards ", " into "])
        {
            var split = spoken.IndexOf(joiner, StringComparison.OrdinalIgnoreCase);

            if (split > 0)
            {
                return Naming.Strip(spoken[..split]);
            }
        }

        return spoken;
    }

    private static void RegisterCombat(CommandRegistry registry)
    {
        CommandResult Strike(GameEngine engine, Session session, string argument)
        {
            var location = engine.CurrentLocation(session);

            if (location?.Monster is not { IsAlive: true } monster)
            {
                return CommandResult.Futile("There is nothing to attack here.");
            }

            // Naming what is in front of you is the commonest way to say it.
            var wanted = Naming.Strip(argument);

            if (wanted.Length > 0 && !monster.Matches(wanted))
            {
                return CommandResult.Futile($"There is no {wanted} here to attack.");
            }

            engine.Attack(session);
            return CommandResult.Done();
        }

        registry.RegisterExact(Strike, "attack", "fight", "kill", "stab");
        registry.RegisterPrefix(Strike, "attack", "fight", "kill", "stab", "attack the", "kill the");

        RegisterLeaving(registry);
    }

    /// <summary>
    /// The way out. Nobody standing in front of a locked door types "exit" first:
    /// they open it, unlock it, turn the key in it. The first person ever to reach
    /// this world's door with the key in hand tried six such sentences, was told
    /// nothing by any of them, and walked away from a door that would have opened.
    /// So every reasonable way of saying it is the same command now, and the
    /// refusals say what is actually wrong rather than that nothing happened.
    ///
    /// What lies past it is <see cref="GameEngine.Escape"/>: the end of that life,
    /// alive.
    /// </summary>
    private static void RegisterLeaving(CommandRegistry registry)
    {
        CommandResult Leave(GameEngine engine, Session session, string _)
        {
            var location = engine.CurrentLocation(session);

            if (location is null || !location.IsExit)
            {
                return CommandResult.Futile("There is no way out here. Sadly, this is not the exit.");
            }

            if (!session.Character.HasKey)
            {
                return CommandResult.Futile(
                    "It is locked, and there is a keyhole in it. Nothing you are carrying fits.");
            }

            engine.Escape(session);
            return CommandResult.Done();
        }

        registry.RegisterExact(Leave,
            "exit", "escape", "leave", "out", "get out", "go out", "way out",
            "open door", "open the door", "open it", "open gate", "open the gate",
            "unlock door", "unlock the door", "unlock it", "unlock",
            "turn key", "turn the key", "use key", "use the key", "use door", "use the door",
            "insert key", "insert the key", "put key in lock", "put the key in the lock",
            "key", "unlock door with key", "unlock the door with the key",
            "open door with key", "open the door with the key",
            "go through door", "go through the door", "enter door", "enter the door",
            "push door", "push the door", "pull door", "pull the door", "knock");

        // Anything of the shape "<verb> the heavy iron door" — but only where
        // there is a door to mean. Elsewhere the room gets its turn untouched.
        registry.RegisterPrefix((engine, session, argument) =>
        {
            var wanted = Naming.Strip(argument);
            var location = engine.CurrentLocation(session);

            if (location is not { IsExit: true })
            {
                return CommandResult.NotHandled;
            }

            return wanted.Contains("door", StringComparison.OrdinalIgnoreCase)
                || wanted.Contains("key", StringComparison.OrdinalIgnoreCase)
                || wanted.Contains("lock", StringComparison.OrdinalIgnoreCase)
                || wanted.Contains("gate", StringComparison.OrdinalIgnoreCase)
                    ? Leave(engine, session, argument)
                    : CommandResult.NotHandled;
        }, "open", "unlock", "turn", "push", "pull", "pry", "force", "enter", "go through", "try");
    }

    /// <summary>
    /// Wanting to stop and mend is one of the first things anyone asks a world
    /// for. The engine does not decide where that is allowed — a place does, with
    /// a heal action — but it recognises the asking everywhere, so the answer is
    /// "not here" rather than silence.
    /// </summary>
    private static void RegisterRest(CommandRegistry registry)
    {
        registry.RegisterExact((_, _, _) => CommandResult.Futile(
                "Not here. You would need somewhere out of the wind, with the makings of a fire."),
            "rest", "sleep", "nap", "recover", "heal", "sit", "sit down", "lie down", "camp", "make camp");
    }

    private static void RegisterSpeech(CommandRegistry registry)
    {
        // Speech is recorded and delivered. The world itself never answers.
        registry.RegisterPrefix((engine, session, argument) =>
        {
            engine.BroadcastToLocation(session.CurrentLocationId,
                $"{session.Character.Name} says: {argument}", except: session);
            session.Write($"You say: {argument}");
            engine.Emit(GameEvent.For(session, EventType.Speech, ("mode", "say"), ("text", argument)));
            return CommandResult.Done();
        }, "say", "speak");

        registry.RegisterPrefix((engine, session, argument) =>
        {
            engine.BroadcastToWorld($"{session.Character.Name} yells: {argument}", except: session);
            session.Write($"You yell: {argument}");
            engine.Emit(GameEvent.For(session, EventType.Speech, ("mode", "yell"), ("text", argument)));
            return CommandResult.Done();
        }, "yell", "shout");

        // Whispering to somebody who is not here.
        //
        // Malcolm played a dead stranger's whistle over the place they died and
        // then typed: "whisper Thank you M R, whoever you where. I'm sorry for
        // what became of you, but am grateful for what you left behind." The
        // world answered "There is no Thank here." — because the first word of
        // anything whispered is read as a player's name, and no player was on.
        //
        // He was not addressing a player. Almost nobody here ever is: this world
        // is empty most hours of the day and the only other people in it are
        // dead. So a whisper with nobody to receive it is not a mistake to be
        // refused. It is left where it was said, for whoever stands there next.
        registry.RegisterPrefix((engine, session, argument) =>
        {
            var split = argument.IndexOf(' ');

            if (split > 0)
            {
                var targetName = argument[..split];
                var text = argument[(split + 1)..];
                var target = engine.Sessions.FirstOrDefault(other =>
                    string.Equals(other.Character.Name, targetName, StringComparison.OrdinalIgnoreCase));

                if (target is not null)
                {
                    target.Write($"{session.Character.Name} whispers: {text}");
                    session.Write($"You whisper to {target.Character.Name}: {text}");
                    engine.Emit(GameEvent.For(session, EventType.Speech,
                        ("mode", "whisper"), ("target", target.CharacterId), ("text", text)));
                    return CommandResult.Done();
                }
            }

            // Nobody of that name is alive and listening — so the whole of it,
            // first word included, was meant for the place.
            engine.LeaveWords(session, argument);
            return CommandResult.Done();
        }, "whisper", "tell");

        // Saying it on purpose to the place rather than to a person.
        registry.RegisterPrefix((engine, session, argument) =>
        {
            engine.LeaveWords(session, argument);
            return CommandResult.Done();
        }, "carve", "scratch", "inscribe", "write", "engrave");

        registry.RegisterExact((_, _, _) => CommandResult.Futile(
                "You could leave something here for whoever comes next. Carve it: carve <whatever you have to say>."),
            "carve", "scratch", "inscribe", "write", "engrave");

        registry.RegisterPrefix((engine, session, argument) =>
        {
            session.Write("You pray.");
            engine.Emit(GameEvent.For(session, EventType.Speech, ("mode", "pray"), ("text", argument)));
            return CommandResult.Done();
        }, "pray");

        registry.RegisterExact((engine, session, _) =>
        {
            session.Write("You pray.");
            engine.Emit(GameEvent.For(session, EventType.Speech, ("mode", "pray"), ("text", "")));
            return CommandResult.Done();
        }, "pray");
    }
}

